float f_32 = 1.0f / 3.0f; // Single precision (7 digits)
double d_64 = 1.0 / 3.0;    // Double precision (15 digits)

// Literal suffixes: 'f' for float, 'L' for long double
long double ld_80 = 2.7L;   // Extended precision (often 80-bit)

// Comparison tolerance required due to precision errors
if (f_32 - 0.333f < 1e-6) {
    // ...
}

// Special values (requires cmath/math.h)
double inf = 1.0 / 0.0;     // Positive Infinity
double nan = 0.0 / 0.0;     // Not a Number (NaN)
// nan != nan is True

// --- Casting and Precision Loss ---

long long massive = 9007199254740993LL; // > 2^53

double d_cast = (double)massive;    // Usually exact (53 bits mantissa)
float f_cast = (float)massive;      // Precision loss (24 bits mantissa)

float pi = 3.14159f;
int i_trunc = (int)pi;      // 3 (Truncates toward zero)

float neg = -3.9f;
int i_neg = (int)neg;       // -3 (Truncates toward zero)

double too_big = 1.0e40;
int i_overflow = (int)too_big; // Undefined Behavior (UB)
                               // if too_big > INT_MAX
